def receive(self, amount: int, physical: bool = True, damage_type: str | None = None) -> int:
    if amount < 0:
        raise ValueError("negative damage")
    if physical and self.shield > 0 and damage_type != "piercing":
        shield_taken = min(self.shield, amount)
        amount -= shield_taken
        self.shield -= shield_taken
    dealt = min(self.hp, amount)
    self.hp -= dealt
    if physical:
        self.alive = self.hp > 0
    else:
        if self.hp < 1:
            self.hp = 1
        self.alive = self.hp > 0
    return dealt

arguments.old:
def receive(self, amount: int, physical: bool = True) -> int:
    if amount < 0:
        raise ValueError("negative damage")
    if physical and self.shield > 0:
        shield_taken = min(self.shield, amount)
        amount -= shield_taken
        self.shield -= shield_taken
    dealt = min(self.hp, amount)
    self.hp -= dealt
    if physical:
        self.alive = self.hp > 0
    else:
        if self.hp < 1:
            self.hp = 1
        self.alive = self.hp > 0
    return dealt
